gofiles=[]
for dp,dn,fn in os.walk(root):
    if any(x in dp for x in ('/node_modules','/.git','/graphify-out','/web')): continue
    for f in fn:
        if f.endswith('.go'): gofiles.append(os.path.join(dp,f))
src={f:open(f,encoding='utf-8',errors='replace').read() for f in gofiles}
def pk(s):
    m=re.search(r'^package\s+(\w+)',s,re.M); return m.group(1) if m else '?'
pkg={f:pk(s) for f,s in src.items()}
pkgdir={}
for f in gofiles: pkgdir.setdefault(os.path.dirname(f),pkg[f])
imports={}
for f,s in src.items():
    imports[f]=set(re.findall(r'"(github\.com/usememos/memos/[^"]+)"',s))

# enclosing function index per file
def encl_index(s):
    idx=[]
    for m in re.finditer(r'^func\s+(?:\(\s*\w+\s+\*?[\w\[\]]+\s*\)\s*)?(\w+)',s,re.M):
        idx.append((m.start(),m.group(1)))
    return idx
enc={f:encl_index(s) for f,s in src.items()}
def encl(f,pos):
    r='<top>'
    for st,n in enc[f]:
        if st<=pos: r=n
        else: break
    return r

decl_meth=re.compile(r'^func\s+\(\s*\w+\s+\*?([\w\[\]]+)\s*\)\s*(\w+)\s*[\(\[]',re.M)
decl_func=re.compile(r'^func\s+(\w+)\s*[\(\[]',re.M)
targets=[]
for f,s in src.items():
    if not f.startswith(root+'/internal/') or f.endswith('_test.go'): continue
    for m in decl_func.finditer(s): targets.append((m.group(1),f,'func',''))
    for m in decl_meth.finditer(s): targets.append((m.group(2),f,'method',m.group(1)))

def relimp(f, declfile):
    """is file f allowed to call into declfile's package?"""
    if os.path.dirname(f)==os.path.dirname(declfile): return True
    rel=os.path.relpath(os.path.dirname(declfile),root)
    return ('github.com/usememos/memos/'+rel) in imports[f]

res=[]; seen=set()
for name,df,kind,recv in targets:
    k=(name,pkg[df],kind,recv)
    if k in seen: continue
    seen.add(k)
    p=pkg[df]
    sites=[]
    for f,s in src.items():
        if not relimp(f,df): continue
        same = os.path.dirname(f)==os.path.dirname(df)
        if kind=='func':
            pat = re.compile(r'(?<![\.\w])'+name+r'\s*\(') if same else re.compile(r'\b'+p+r'\.'+name+r'\s*\(')
        else:
            pat = re.compile(r'\.'+name+r'\s*\(')
        for m in pat.finditer(s):
            line=s[:m.start()].count('\n')+1
            e=encl(f,m.start())
            if kind=='func' and same and re.match(r'^\s*func\s',s[s.rfind('\n',0,m.start())+1:m.start()+1] or ''): continue
            # skip declaration line
            ls=s.rfind('\n',0,m.start())+1
            if s[ls:m.start()].strip().startswith('func'): continue
            sites.append((os.path.relpath(f,root),line,e,f.endswith('_test.go')))
    prod=[x for x in sites if not x[3]]
    res.append((len(sites),len(prod),len({(x[0],x[2]) for x in sites}),len({(x[0],x[2]) for x in prod}),name,p,recv,os.path.relpath(df,root)))
res.sort(key=lambda r:-r[0])
print(f"{'sites':>6}{'prodS':>6}{'callers':>8}{'prodC':>6}  symbol")
for r in res[:30]:
    print(f"{r[0]:>6}{r[1]:>6}{r[2]:>8}{r[3]:>6}  {r[5]}.{r[6]+'.' if r[6] else ''}{r[4]}  [{r[7]}]")
EOF
